head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[tabControl > P > useATagBtn]<br/>웹접근성 향상을 위해 Tab 버튼 영역의 '닫기' 버튼을 a 태그로 렌더링할지 설정합니다.",
    "validation" : [
        "Tabs 의 closable 속성값에 관계없이 TabControl 의 closable 속성이 true 인 경우에 동작합니다.",
        "미설정 또는 false 설정 시 Tab 버튼 영역의 '닫기' 버튼을 div 태그로 렌더링합니다.",
        "true 설정 시 Tab 버튼 영역의 '닫기' 버튼을 a 태그로 렌더링합니다.",
        "true 설정 시 a 태그의 class 속성에 'w2tabcontrol_tab_close_atag' 클래스가 설정됩니다.",
        "a 태그로 렌더링 시 키보드를 통한 '닫기' 버튼 제어가 가능합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        closable : true,
        alwaysShowCloseBtn : true,
        useATagBtn : con_useATagBtn.getText(),
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["ontabclose"]);

    $c.gcm.createBasicTabControl(cList, eList);

    scwin.getTabButtonInfo();
}



scwin.getTabButtonInfo = function () {    
    setTimeout(function () {
        const tabsId = [
            '[id*=target1_tab_tabs1_close]',
            '[id*=target1_tab_tabs2_close]',
            '[id*=target1_tab_tabs3_close]',
        ]

        tabsId.forEach((tabId, index) => {
            let closeButton = document.querySelector(tabId);
            let closeButtonTagName = closeButton.tagName;
            let closeButtonClassName = closeButton.className;

            wf_body_bottom.getObj("scwin").setReturnValue(`closeButton${index + 1} tagName: ${closeButtonTagName}`);
            wf_body_bottom.getObj("scwin").setReturnValue(`closeButton${index + 1} className: ${closeButtonClassName}`);
        });
    }, 1000);
}



scwin.target1_ontabclose = function (tabId, index, userTabId) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_ontabclose=====");
}
